// Üretilen dosya: tool/ozgun/uret.py. Edebiyat · Türk edebiyatı: Tanzimat'tan Cumhuriyet'e yazarlar ve eserler (kolay).
const ozLiterature2Kolay = <(String, String, List<String>, String)>[
  ('Türk edebiyatında "Tanzimat dönemi" adlandırmasının başlangıç noktası olarak kabul edilen siyasi olay hangisidir?', '1839\'da Gülhane Hatt-ı Hümayunu\'nun okunması', ['1876\'da Kanun-ı Esasi\'nin ilan edilmesi', '1826\'da Yeniçeri Ocağı\'nın kaldırılıp Asakir-i Mansure\'nin kurulması', '1856\'da Islahat Fermanı\'nın yayımlanması'], 'Edebiyat tarihçileri dönemi, Tanzimat Fermanı olarak da bilinen 1839 Gülhane Hatt-ı Hümayunu ile başlatır. Edebî ürünler ise asıl 1860\'tan sonra yoğunlaşır.'),
  ('Namık Kemal ve Ziya Paşa\'nın Avrupa\'ya kaçtıktan sonra 1868\'de Londra\'da çıkardıkları gazete hangisidir?', 'Hürriyet', ['İbret', 'Muhbir', 'Diyojen'], 'Yeni Osmanlılar adına Londra\'da çıkarılan Hürriyet gazetesinde Ziya Paşa\'nın "Şiir ve İnşa" makalesi de yayımlanmıştır.'),
  ('Teodor Kasap\'ın 1870\'te çıkardığı Diyojen\'in Türk basın tarihindeki önemi nedir?', 'Türkçe yayımlanan ilk mizah gazetesi olması', ['İlk resmî gazete olması', 'Osmanlı\'da kadınlar için çıkarılan ilk dergi olması', 'İlk bilim dergisi olması'], 'Diyojen, adını Yunan filozofundan alan ve hicivli yazılar yayımlayan ilk Türkçe mizah gazetesidir.'),
  ('Tanzimat sanatçılarının gazeteyi bu kadar önemsemelerinin temel nedeni olarak en doğru açıklama hangisidir?', 'Halkı eğitmek ve yeni fikirleri geniş kitlelere ulaştırmak istemeleri', ['Divan şairlerinin saraydan aldığı ödülleri kendileri de almak istemeleri', 'Gazetelerin yalnız saray çevresince okunması ve bunun prestij sağlaması', 'Kitap basımının o yıllarda yasak olması ve başka yol bulunmaması'], 'Tanzimat yazarları sanatı toplumu aydınlatma aracı olarak gördüler; gazete bu amaca en uygun, en yaygın araçtı.'),
  ('Tanzimat döneminde Batılı anlamda ilk kez denenen türler arasında aşağıdakilerden hangisi yer almaz?', 'Gazel', ['Roman', 'Tiyatro', 'Makale'], 'Gazel Divan edebiyatının köklü bir nazım biçimidir; roman, tiyatro ve makale ise Tanzimat\'ta Batı\'dan alınarak denenen türlerdir.'),
  ('Tanzimat ikinci kuşağı ile birinci kuşak karşılaştırıldığında ikinci kuşağın ayırıcı özelliği hangisidir?', 'Toplumsal konular yerine bireysel duygulara yönelmeleri', ['Şiirde yalnız hece ölçüsünü kullanmaları', 'Divan edebiyatını bütün kurallarıyla savunup yeniliğe karşı çıkmaları', 'Gazeteciliği edebiyatın merkezine koymaları'], 'Siyasi baskıların arttığı II. Abdülhamit yıllarında ikinci kuşak aşk, ölüm, doğa gibi bireysel temalara yöneldi.'),
  ('Yusuf Kâmil Paşa\'nın Türk edebiyatına kazandırdığı Telemak çevirisinin önemi nedir?', 'Batı edebiyatından yapılan ilk roman çevirisi olması', ['Türkçe yazılmış ilk yerli roman olması', 'İlk Türkçe tiyatro oyunu olması', 'Divan şiirinden Fransızcaya yapılmış ilk kapsamlı çeviri olması'], 'Fénelon\'un Les Aventures de Télémaque adlı eserinin 1859\'da yapılan bu çevirisi, Batı\'dan Türkçeye aktarılan ilk roman olarak kabul edilir.'),
  ('Vatan yahut Silistre\'nin sahnelenmesinin ardından yaşanan olaylar Namık Kemal için nasıl bir sonuç doğurmuştur?', 'Kıbrıs\'taki Magosa\'ya sürgün edilmiştir.', ['Saraya başkâtip olarak atanmıştır.', 'Londra\'ya elçi olarak gönderilmiştir.', 'Paris\'te tiyatro eğitimi almak üzere burs kazanmıştır.'], 'Oyunun seyircide uyandırdığı coşku yönetimi kaygılandırdı; Namık Kemal 1873\'te Magosa\'ya sürüldü ve burada yaklaşık üç yıl kaldı.'),
  ('Türk edebiyatında Batılı anlamda yazılmış ilk tiyatro eseri olarak kabul edilen oyun hangisidir?', 'Şair Evlenmesi', ['Vatan yahut Silistre', 'Zavallı Çocuk', 'Akif Bey'], 'Şinasi\'nin tek perdelik töre komedisi Şair Evlenmesi (1860), Batı tekniğiyle yazılmış ilk Türk tiyatro eseridir.'),
  ('Şair Evlenmesi\'nde eleştirilen toplumsal sorun hangisidir?', 'Görücü usulüyle evlenme ve bunun yol açtığı aldatmacalar', ['Rüşvet yüzünden devlet işlerinin aksaması', 'Alafranga yaşama özenmenin aileyi dağıtması ve borçlandırması', 'Köylünün ağalar tarafından ezilmesi'], 'Müştak Bey görmeden istediği Kumru yerine çirkin ablası Sakine ile evlendirilir; oyun görücü usulünü ve imamın aracılığını alaya alır.'),
  ('Şinasi\'nin Türk atasözlerini derleyip yayımladığı eser hangisidir?', 'Durub-ı Emsal-i Osmaniye', ['Müntehabat-ı Eş\'ar', 'Tercüme-i Manzume', 'Kamus-ı Türki'], 'Durub-ı Emsal-i Osmaniye (1863), Şinasi\'nin halk dilinin zenginliğini gösterme çabasının ürünü olan atasözleri derlemesidir.'),
  ('"Halk için sanat" ilkesini Şinasi ile birlikte başlatan Tanzimat yazarlarından biri yeni bir gazete çıkarmak istese, Şinasi\'nin anlayışına göre öncelikle aşağıdakilerden hangisine dikkat etmesi beklenir?', 'Halkın anlayacağı sade bir dil kullanmaya', ['Arapça ve Farsça tamlamalarla süslü bir üslup kurmaya', 'Yazılarını yalnız manzum olarak yayımlamaya', 'Gazeteyi yalnız saray çevresine dağıtmaya'], 'Şinasi\'nin gazetecilik anlayışının merkezinde halkın anlayacağı dille yazmak ve onu bilgilendirmek vardır.'),
  ('Namık Kemal\'e "vatan şairi" ve "hürriyet şairi" denmesinin nedeni hangisidir?', 'Şiirlerinde vatan ve hürriyet kavramlarını coşkulu biçimde işlemesi', ['Bütün şiirlerini hece ölçüsüyle yazması', 'Halk şiiri biçimlerini Divan şiirine tercih ederek koşma ve semailer yazması', 'Aşk şiirlerini Batı\'dan çevirmesi'], 'Namık Kemal, vatan ve hürriyet kavramlarını Türk şiirine yerleştiren ve bunları heyecanla işleyen şairdir.'),
  ('"Ne efsunkâr imişsin âh ey dîdâr-ı hürriyet / Esîr-i aşkın olduk gerçi kurtulduk esâretten" beyitleri Namık Kemal\'in hangi şiirinden alınmıştır?', 'Hürriyet Kasidesi', ['Vatan Mersiyesi', 'Terkib-i Bend', 'Makber'], 'Hürriyet Kasidesi, Namık Kemal\'in hürriyet kavramını sevgili gibi ele aldığı ünlü kasidesidir.'),
  ('Namık Kemal\'in şiirlerinde Divan şiiri ile ilişkisi için aşağıdakilerden hangisi doğrudur?', 'Yeni kavramları kaside, gazel, terkib-i bend gibi eski biçimlerle işlemiştir.', ['Divan nazım biçimlerini hiç kullanmamış, yalnız sone ve terza rima biçimlerinde yazmıştır.', 'Şiirlerinin tamamını serbest ölçüyle yazmıştır.', 'Yalnız tasavvufi gazeller yazmıştır.'], 'Namık Kemal içerikte yenilikçi, biçimde ise büyük ölçüde gelenekçidir; vatan ve hürriyet fikirlerini aruzla, Divan biçimleriyle söyler.'),
  ('Namık Kemal\'in Türk edebiyatının ilk edebî romanı sayılan eseri hangisidir?', 'İntibah', ['Cezmi', 'Zavallı Çocuk', 'Celâleddin Harzemşah'], 'İntibah (1876), Tanzimat\'ta yazılmış romanlar içinde edebî değeri en yüksek ilk örnek olarak kabul edilir.'),
  ('İntibah\'ta Ali Bey\'i kendine bağlayan ve olayların felaketle sonuçlanmasına yol açan kadın kahraman kimdir?', 'Mehpeyker', ['Dilaşub', 'Periveş', 'Bihter'], 'Ali Bey, Çamlıca\'da tanıştığı Mehpeyker\'e tutulur; ona sadakatle bağlanan cariye Dilaşub ise Mehpeyker\'in kurduğu tuzağın kurbanı olur.'),
  ('Vatan yahut Silistre oyununun konusu aşağıdakilerden hangisidir?', '1853-54\'te Rus kuşatması altındaki Silistre\'yi savunan gönüllülerin kahramanlığı', ['Kırım hanlarının iç çatışmaları ve taht kavgası', 'Endülüs\'ün Tarık bin Ziyad komutasındaki Müslümanlarca fethi ve sonrası', 'Görücü usulü evliliğin yol açtığı aile dramı'], 'Oyun, Kırım Savaşı sırasında Silistre kalesini savunan İslam Bey ve onu erkek kılığında izleyen Zekiye\'nin vatan için fedakârlığını işler.'),
  ('Namık Kemal\'in Ziya Paşa\'nın hazırladığı Harabat adlı seçkiyi eleştirmek için yazdığı eser hangisidir?', 'Tahrib-i Harabat', ['Mukaddime-i Celal', 'Renan Müdafaanamesi', 'Evrak-ı Perişan'], 'Tahrib-i Harabat ve devamı Takip, Harabat\'taki seçimleri ve Ziya Paşa\'nın Divan şiirine dönüşünü sert biçimde eleştirir.'),
  ('"Âyinesi iştir kişinin lâfa bakılmaz / Şahsın görünür rütbe-i aklı eserinde" beytini içeren ünlü manzume hangi şaire aittir?', 'Ziya Paşa', ['Namık Kemal', 'Şinasi', 'Muallim Naci'], 'Bu beyit Ziya Paşa\'nın Terkib-i Bend\'inden alınmıştır ve kişinin değerinin sözüyle değil işiyle ölçüleceğini anlatır.'),
  ('Ahmet Mithat Efendi\'ye "hâce-i evvel" (ilk öğretmen) denmesinin nedeni hangisidir?', 'Halkı okutmayı ve bilgilendirmeyi amaçlayan çok sayıda eser yazması', ['İlk Türk üniversitesini kurması', 'Sultanın özel öğretmeni olarak görev yapması', 'Yalnız okullar için ders kitabı yazıp edebî türlerde hiçbir eser vermemiş olması'], 'Ahmet Mithat, halkı okumaya alıştırmak ve eğitmek için roman, hikâye, makale gibi pek çok türde yüzlerce eser yazmıştır.'),
  ('Ahmet Mithat\'ın Felatun Bey ile Rakım Efendi romanında karşıtlık yoluyla verilen temel düşünce hangisidir?', 'Batılılaşmanın yanlış anlaşılmasının yol açtığı yozlaşma', ['Köy hayatının şehir hayatından üstün olduğu', 'Tarihî kahramanların günümüze örnek olduğu', 'Tasavvufun insanlara dünya işlerinden uzak durmayı öğütlediği'], 'Savurgan ve özenti Felatun Bey ile çalışkan, kendi kültürüne bağlı Rakım Efendi karşılaştırılarak yüzeysel Batılılaşma eleştirilir.'),
  ('Türk romanında "alafranga züppe" tipinin ilk örneği sayılan kahraman kimdir?', 'Felatun Bey', ['Bihruz Bey', 'Meftun Bey', 'Ahmet Cemil Bey'], 'Felatun Bey (1875) bu tipin ilk örneğidir; Araba Sevdası\'ndaki Bihruz Bey ve Şıpsevdi\'deki Meftun Bey ondan sonra gelen örneklerdir.'),
  ('Felatun Bey ile Rakım Efendi\'de Rakım Efendi\'nin özellikleri arasında aşağıdakilerden hangisi yer almaz?', 'Babasından kalan mirası eğlenceye harcaması', ['Çalışkan ve tutumlu olması', 'Yabancı dil bilmesi ve çeviri yapması', 'Kendi kültürüne bağlı kalarak Batı\'dan yararlanması'], 'Mirası eğlenceye harcayan Felatun Bey\'dir; Rakım Efendi çalışarak kendini yetiştiren, Fransızca bilen ve çeviri yapan olumlu tiptir.'),
  ('Ahmet Mithat\'ın romanlarında anlatıcının olayları kesip okura doğrudan seslenmesi ve bilgi vermesi hangi amaca hizmet eder?', 'Okuru eğitmek ve bilgilendirmek', ['Olay örgüsünü daha gizemli kılmak', 'Gerçekçiliği en üst düzeye çıkarmak', 'Kahramanların iç dünyasını derinleştirmek'], 'Ahmet Mithat okuruyla sohbet eder gibi yazar; araya girip tarih, coğrafya, ahlak gibi konularda bilgi verir. Bu, eğitici amacının ürünüdür ama roman tekniği bakımından kusur sayılır.'),
  ('Türk edebiyatında yazılmış ilk yerli roman olarak kabul edilen eser hangisidir?', 'Taaşşuk-ı Talat ve Fitnat', ['İntibah', 'Felatun Bey ile Rakım Efendi', 'Sergüzeşt-i Ali Bey ve Mehpeyker'], 'Şemsettin Sami\'nin 1872\'de tefrika edilen Taaşşuk-ı Talat ve Fitnat\'ı ilk yerli roman kabul edilir.'),
  ('Taaşşuk-ı Talat ve Fitnat romanında işlenen ana sorun nedir?', 'Görücü usulü evlilik ve kadının eşini seçme hakkı', ['Köylünün toprak ağaları tarafından sömürülmesi ve göçe zorlanması', 'Alafranga özentisinin aile ekonomisini çökertmesi', 'Kölelik ve cariyelik kurumunun yol açtığı dramlar'], 'Talat ile Fitnat\'ın birbirini sevmesine rağmen Fitnat\'ın başkasıyla evlendirilmek istenmesi görücü usulünü eleştirir; roman trajik biçimde biter.'),
  ('Aşağıdaki sanatçılardan hangisi Tanzimat ikinci kuşağında yer almaz?', 'Şinasi', ['Recaizade Mahmut Ekrem', 'Abdülhak Hamit Tarhan', 'Sami Paşazade Sezai'], 'Şinasi birinci kuşağın kurucusudur; diğer üç sanatçı ikinci kuşakta yer alır.'),
  ('Recaizade Mahmut Ekrem\'in Araba Sevdası romanının kahramanı Bihruz Bey hangi tipin örneğidir?', 'Batı\'yı yüzeysel olarak taklit eden alafranga züppe', ['Vatanı için savaşan idealist asker', 'Köyünü terk etmeyen geleneksel köylü', 'Kendi kendini yetiştirmiş, tutumlu ve çalışkan bir kâtip'], 'Bihruz Bey, Fransızca kelimeleri yanlış kullanan, lüks arabasıyla gezen, gösteriş meraklısı alafranga bir züppedir.'),
  ('Araba Sevdası\'nda Bihruz Bey\'in Çamlıca\'da gördüğü ve kibar bir aileden geldiğini sandığı kadının adı nedir?', 'Periveş', ['Mehpeyker', 'Dilber', 'Sakine'], 'Periveş aslında sıradan bir kadındır; Bihruz Bey onu kendi hayal dünyasında romantik bir kahramana dönüştürür.'),
  ('Recaizade Mahmut Ekrem\'in "Tefekkür" ve "Yadigâr-ı Şebab" gibi eserlerinde öne çıkan duygu hangisidir?', 'Hüzün ve kötümserlik', ['Coşkulu kahramanlık ve zafer sevinci', 'Siyasi öfke', 'Mizahi alay'], 'Recaizade\'nin şiirleri büyük ölçüde hüzünlü, içli ve kötümser bir hava taşır; ölüm ve kayıp temaları sıktır.'),
  ('Abdülhak Hamit Tarhan\'a verilen "Şair-i Âzam" unvanının anlamı nedir?', 'En büyük şair', ['Halkın şairi', 'Sarayın baş şairi', 'Vatan şairi'], '"Şair-i Âzam" en büyük şair demektir; Abdülhak Hamit\'in Türk şiirine getirdiği yenilikler nedeniyle bu unvanla anılır.'),
  ('Abdülhak Hamit\'in eşi Fatma Hanım\'ın Beyrut\'ta ölümü üzerine yazdığı ünlü eser hangisidir?', 'Makber', ['Sahra', 'Bunlar O\'dur', 'Divaneliklerim yahut Belde'], 'Makber (1885), Türk edebiyatının en tanınmış mersiye kitaplarından biridir; Ölü ve Bunlar O\'dur da aynı acının ürünleridir.'),
  ('Türk edebiyatında Batılı anlamda pastoral (kır ve doğa) şiirin ilk örneği sayılan eser hangisidir?', 'Sahra', ['Makber', 'Zemzeme', 'Rübab-ı Şikeste'], 'Abdülhak Hamit\'in Sahra\'sı (1879), şehir ile köy hayatını karşılaştıran ilk pastoral şiir kitabıdır.'),
  ('Abdülhak Hamit\'in Endülüs\'ün fethini konu alan oyunu hangisidir?', 'Tarık yahut Endülüs Fethi', ['Eşber', 'Finten', 'Sardanapal yahut Asur\'un Çöküşü'], 'Tarık (1879), Tarık bin Ziyad\'ın İspanya\'ya geçişini ve Endülüs\'ün fethini işler.'),
  ('Sami Paşazade Sezai\'nin Türk edebiyatında köleliği eleştiren romanı hangisidir?', 'Sergüzeşt', ['Zehra', 'Karabibik', 'Felâtun Bey ile Râkım Efendi'], 'Sergüzeşt (1889), Kafkasya\'dan kaçırılıp satılan cariye Dilber\'in acıklı hayatı üzerinden esaret kurumunu eleştirir.'),
  ('Sergüzeşt romanının sonunda Dilber\'in yaşadıkları için hangisi doğrudur?', 'Mısır\'a satılır ve sonunda kendini Nil\'e atar.', ['Sevdiği Celal Bey ile evlenip mutlu olur.', 'Ailesine kavuşup Kafkasya\'daki köyüne döner ve orada evlenir.', 'Okul açıp öğretmenlik yapar.'], 'Celal Bey\'den ayrılmak zorunda kalan Dilber Mısır\'a satılır ve Nil\'e atlayarak hayatına son verir.'),
  ('Türk edebiyatında köy hayatını konu edinen ilk eser hangisidir?', 'Karabibik', ['Yaban', 'Çalıkuşu', 'Sahra adlı pastoral şiirler'], 'Nabizade Nazım\'ın Karabibik\'i (1890), Antalya\'nın bir köyünde geçen ve bir köylünün öküz alma derdini anlatan ilk köy anlatısıdır.'),
  ('Karabibik\'te anlatılan köylünün temel derdi nedir?', 'Tarlasını sürmek için öküz edinmek', ['Kızını şehirdeki bir memura vermek', 'Askere giden oğlunu cepheden geri getirtmek', 'Köydeki okulun açılmasını sağlamak'], 'Karabibik\'in en büyük sorunu çift sürecek öküzü olmamasıdır; olaylar bu ekonomik sıkıntı etrafında gelişir.'),
  ('Zehra romanında kahramanı felakete sürükleyen temel duygu hangisidir?', 'Kıskançlık', ['Vatan özlemi', 'Açgözlülük', 'Dinî bağnazlık'], 'Zehra, kocası Suphi\'nin cariye Sırrıcelal ile ilişkisi yüzünden kıskançlık krizlerine girer ve bu duygu onu yıkıma götürür.'),
  ('Muallim Naci\'nin hazırladığı ve sözlük türündeki eseri hangisidir?', 'Lügat-ı Naci', ['Kamus-ı Türki', 'Lehçe-i Osmani', 'Kamusü\'l-a\'lam ve Lügat-ı Osmani'], 'Lügat-ı Naci, Muallim Naci\'nin Arapça ve Farsça kökenli kelimeleri de içeren Türkçe sözlüğüdür.'),
  ('Aşağıdaki romanlardan hangisi Fatma Aliye Hanım\'a aittir?', 'Muhadarat', ['Handan', 'Sinekli Bakkal', 'Aydemir'], 'Muhadarat (1892), Fatma Aliye Hanım\'ın romanıdır; Handan ve Sinekli Bakkal Halide Edib\'in, Aydemir Müfide Ferit Tek\'indir.'),
  ('Tanzimat romanlarında olayların sıklıkla tesadüflerle ilerlemesi ve beklenmedik karşılaşmalar, bu romanların hangi kusurunu gösterir?', 'Olay örgüsünün inandırıcılıktan uzak olması', ['Kişilerin iç dünyalarının fazla derin işlenmesi', 'Dilin fazla sade ve konuşma diline yakın olması', 'Tasvirlerin bilimsel ayrıntılarla yüklenmesi'], 'Tesadüfe dayalı kurgu, Tanzimat romanının teknik açıdan acemi yönlerinden biridir ve olay örgüsünün inandırıcılığını zayıflatır.'),
  ('Tanzimat romanında kişilerin "iyi" ve "kötü" diye kesin çizgilerle ayrılmasının sonucu hangisidir?', 'Karakterlerin tek boyutlu, derinlikten yoksun olması', ['Romanların psikolojik çözümleme bakımından çok güçlü olması', 'Okurun kahramanlar hakkında karar verememesi', 'Romanların çoğunun açık uçlu bitip okura yorum bırakması'], 'İyi-kötü karşıtlığı Tanzimat romanının öğretici amacına uygundur ama kişilerin tek yönlü, tip düzeyinde kalmasına yol açar.'),
  ('Tanzimat romancılarının en sık işlediği konular arasında aşağıdakilerden hangisi yer almaz?', 'Kurtuluş Savaşı\'nda Anadolu halkının direnişi', ['Yanlış Batılılaşma', 'Esaret ve cariyelik kurumunun yol açtığı acılar', 'Görücü usulü evlilik'], 'Kurtuluş Savaşı, Millî Edebiyat ve Cumhuriyet döneminde işlenen bir konudur; diğerleri Tanzimat romanının tipik konularıdır.'),
  ('Tanzimat romancılarının Batı romanını örnek alırken en çok yararlandıkları edebî akım hangisidir?', 'Romantizm', ['Sembolizm', 'Fütürizm', 'Sürrealizm'], 'Tanzimat romanı başta Fransız romantizminin etkisindedir; ikinci kuşakta realizme ve natüralizme doğru bir yöneliş başlar.'),
  ('Hüseyin Rahmi Gürpınar\'ın sanat anlayışını en iyi özetleyen yargı hangisidir?', 'İstanbul\'un mahalle hayatını mizahi bir dille, gözleme dayalı olarak yansıtması', ['Yalnız saray çevresini ve paşa konaklarını anlatıp halkın gündelik hayatından tümüyle uzak durması', 'Şiiri romanın önüne koyarak yalnız manzum eserler yazması', 'Eserlerini ağır bir Arapça ve Farsça ile yazması'], 'Hüseyin Rahmi, İstanbul\'un orta ve alt tabakasını, konuşma diline yakın bir dille ve mizah unsurlarıyla anlatmıştır.'),
  ('Hüseyin Rahmi Gürpınar\'ın kendisini yetiştiren ve izinden gittiği usta kabul ettiği yazar kimdir?', 'Ahmet Mithat Efendi', ['Namık Kemal', 'Halit Ziya Uşaklıgil', 'Tevfik Fikret'], 'Hüseyin Rahmi, halka seslenme ve eğitici amaç bakımından Ahmet Mithat\'ın yolunu izlemiş, onu ustası saymıştır.'),
  ('Hüseyin Rahmi Gürpınar\'ın 1910\'da Halley kuyruklu yıldızının dünyaya yaklaşmasının yarattığı paniği işlediği romanı hangisidir?', 'Kuyruklu Yıldız Altında Bir İzdivaç', ['Gulyabani', 'Şıpsevdi', 'Gönül Bir Yel Değirmenidir'], 'Kuyruklu Yıldız Altında Bir İzdivaç, Halley kuyruklu yıldızı çevresindeki batıl korkuları mizahla ele alır.'),
  ('Hüseyin Rahmi Gürpınar\'ın Şıpsevdi romanında alaya aldığı tip hangisidir?', 'Alafranga züppe', ['Bağnaz softa', 'Cimri ve açgözlü tefeci', 'Korkak asker'], 'Şıpsevdi\'nin kahramanı Meftun Bey, Felatun Bey ve Bihruz Bey çizgisinde bir alafranga züppedir.'),
  ('Hüseyin Rahmi Gürpınar\'ın Gulyabani gibi romanlarında sıkça yöneldiği eleştiri konusu hangisidir?', 'Batıl inançlar ve hurafeler', ['Askerî yenilgiler', 'Saray entrikaları ve taht kavgaları', 'Dil tartışmaları'], 'Gulyabani ve Cadı gibi eserlerde Hüseyin Rahmi, korku ve gizem havası kurup sonunda bunların aldatmaca olduğunu göstererek batıl inançları eleştirir.'),
  ('Servet-i Fünun topluluğu için kullanılan bir diğer ad hangisidir?', 'Edebiyat-ı Cedide', ['Fecr-i Âti', 'Genç Kalemler', 'Yedi Meşaleciler Topluluğu'], '"Yeni edebiyat" anlamındaki Edebiyat-ı Cedide, Servet-i Fünun topluluğunun diğer adıdır.'),
  ('Servet-i Fünun dergisinin 1901\'de kapatılmasına yol açan yazı hangisidir?', 'Hüseyin Cahit\'in Fransızcadan çevirdiği "Edebiyat ve Hukuk"', ['Ahmet Mithat\'ın Sabah gazetesindeki "Dekadanlar" makalesi', 'Ömer Seyfettin\'in "Yeni Lisan" makalesi', 'Tevfik Fikret\'in "Sis" şiiri'], 'Fransız İhtilali\'ne olumlu değinen bu çeviri yazı, sansür tarafından zararlı bulununca dergi kapatıldı ve topluluk dağıldı.'),
  ('Servet-i Fünun sanatçılarının dil anlayışı için hangisi doğrudur?', 'Arapça ve Farsça kelime ve tamlamaları yoğun kullanan ağır bir dil', ['Yalnız konuşma diline dayanan sade bir dil', 'Yabancı kelimelerden tamamen arındırılmış, yalnız Türkçe köklerden türetilmiş öz bir dil', 'Halk şiirinin ağız özelliklerini yansıtan bir dil'], 'Servet-i Fünuncular sözlüklerden bulup çıkardıkları kelimeler ve yeni tamlamalarla ağır, seçkinlere seslenen bir dil kullandılar.'),
  ('Servet-i Fünun şiirinde etkili olan Fransız akımları hangileridir?', 'Parnasizm ve sembolizm', ['Klasisizm ve fütürizm', 'Sürrealizm ve dadaizm', 'Ekspresyonizm ve kübizm'], 'Servet-i Fünun şairleri özellikle parnasizmin biçim titizliğinden ve sembolizmin müzikal, imgeli anlatımından etkilenmiştir.'),
  ('Servet-i Fünun yazarlarının romanda benimsediği akım hangisidir?', 'Realizm', ['Sembolizm', 'Klasisizm', 'Sürrealizm'], 'Halit Ziya ve Mehmet Rauf başta olmak üzere Servet-i Fünun romancıları realizmi ve kısmen natüralizmi benimsemiştir.'),
  ('Tevfik Fikret\'in ilk şiir kitabı olan ve bireysel duygularını yansıtan eseri hangisidir?', 'Rübab-ı Şikeste', ['Haluk\'un Defteri', 'Şermin', 'Rübabın Cevabı'], 'Rübab-ı Şikeste (1900), "kırık saz" anlamına gelir; Fikret\'in Servet-i Fünun dönemi bireysel şiirlerini içerir.'),
  ('Tevfik Fikret\'in İstanbul\'u sisle örtülü, ahlakı bozulmuş bir şehir olarak eleştirdiği şiiri hangisidir?', 'Sis', ['Han-ı Yağma', 'Balıkçılar', 'Ferda'], 'Sis, İstanbul\'un ve dolayısıyla dönemin yönetiminin yozlaşmasını sert bir dille eleştirir.'),
  ('Tevfik Fikret\'in oğluna seslenerek yazdığı ve geleceğe dair umutlarını dile getirdiği şiirlerini topladığı kitap hangisidir?', 'Haluk\'un Defteri', ['Rübab-ı Şikeste', 'Şermin', 'Ömer\'in Çocukluğu'], 'Haluk\'un Defteri (1911), oğlu Haluk\'u merkeze alan, eğitici ve idealist şiirlerden oluşur.'),
  ('Tevfik Fikret\'in çocuklar için yazdığı, sade Türkçesiyle dikkat çeken şiir kitabı hangisidir?', 'Şermin', ['Ferda', 'Haluk\'un Defteri', 'Rübabın Cevabı'], 'Şermin (1914), çocuklara yönelik, aruzla ama oldukça sade bir dille yazılmış şiirlerden oluşur.'),
  ('Tevfik Fikret\'in yoksul bir balıkçı ailesinin çaresizliğini işlediği toplumsal içerikli şiiri hangisidir?', 'Balıkçılar', ['Sis', 'Promete', 'Millet Şarkısı'], 'Balıkçılar\'da kışın denize açılamayan yoksul bir balıkçının ailesinin açlığı anlatılır; Fikret\'in sosyal yönlü şiirlerindendir.'),
  ('Tevfik Fikret\'in "Ferda" şiirinde seslendiği kesim kimdir?', 'Gençler', ['Padişah', 'Askerler', 'Şairler'], '"Ferda" (yarın) şiirinde Fikret, geleceğin gençlere ait olduğunu söyler ve onlara görevlerini hatırlatır.'),
  ('Tevfik Fikret\'in Rumelihisarı\'nda kendi tasarladığı ve bugün müze olan evinin adı nedir?', 'Aşiyan', ['Lâne', 'Yuva-i Fikret', 'Bülbülderesi'], 'Aşiyan "kuş yuvası" anlamındadır; Fikret\'in ölümüne kadar yaşadığı ev bugün Aşiyan Müzesi olarak kullanılmaktadır.'),
  ('Cenap Şahabettin\'in "Elhan-ı Şita" şiiri hangi doğa olayını işleyerek tanınmıştır?', 'Kar yağışı ve kış', ['Bahar ve çiçeklenme', 'Deniz fırtınası', 'Yaz sıcağı'], '"Kış nağmeleri" anlamına gelen Elhan-ı Şita, kar yağışını ve kış manzarasını ses ve renk ahengiyle verir.'),
  ('Halit Ziya Uşaklıgil\'in Türk edebiyatında Batılı anlamda ilk başarılı roman sayılan eseri hangisidir?', 'Mai ve Siyah', ['Nemide', 'Ferdi ve Şürekası', 'Bir Ölünün Defteri'], 'Mai ve Siyah (1897), teknik olgunluğu ve gerçekçi yapısıyla Batı tarzı romanın Türk edebiyatındaki ilk başarılı örneği sayılır.'),
  ('Mai ve Siyah romanının adındaki iki rengin simgelediği kavramlar hangi seçenekte doğru verilmiştir?', 'Mavi: hayaller; siyah: hayal kırıklığı ve acı gerçek', ['Mavi: geçmişin güzellikleri; siyah: belirsiz gelecek', 'Mavi: zenginlik; siyah: yoksulluk', 'Mavi: deniz; siyah: gece'], 'Ahmet Cemil\'in mavi hayalleri ile karşılaştığı kara gerçekler romanın başlığında simgeleşmiştir.'),
  ('Mai ve Siyah\'ın başkahramanı Ahmet Cemil\'in en büyük hayali nedir?', 'Büyük bir şiir kitabı yazıp ün kazanmak', ['Paris\'te bir lokanta açmak', 'Saraya kâtip olarak girip kısa sürede paşa rütbesine yükselmek', 'Anadolu\'da çiftlik kurmak'], 'Ahmet Cemil, edebiyata yeni bir soluk getirecek büyük bir eser yazmayı hayal eder; ancak hayat şartları onu yenilgiye uğratır.'),
  ('Halit Ziya\'nın Aşk-ı Memnu romanında yaşlı Adnan Bey ile evlenen genç kadın kahraman kimdir?', 'Bihter', ['Nihal', 'Firdevs Hanım', 'Peyker'], 'Bihter, annesi Firdevs Hanım\'ın sosyete yaşamından uzaklaşmak için Adnan Bey ile evlenir; sonra Behlül ile yasak bir ilişkiye girer.'),
  ('Aşk-ı Memnu\'nda Bihter\'in yasak ilişki yaşadığı ve Adnan Bey\'in yeğeni olan kişi kimdir?', 'Behlül', ['Ahmet Cemil', 'Necip', 'Bihruz'], 'Behlül, yalıda yaşayan, hafifmeşrep bir gençtir; Bihter\'le ilişkisi romanın trajik sonunu hazırlar.'),
  ('Aşk-ı Memnu\'nun olaylarının büyük bölümünün geçtiği mekân hangisidir?', 'Boğaziçi\'nde bir yalı', ['Anadolu\'da bir köy konağı', 'Beyoğlu\'nda bir apartman', 'Heybeliada\'da bir köşk'], 'Adnan Bey\'in Boğaziçi\'ndeki yalısı, romanın kapalı ve dar mekânıdır; olaylar büyük ölçüde bu yalıda geçer.'),
  ('Türk edebiyatında Batılı anlamda ilk başarılı psikolojik roman olarak kabul edilen eser hangisidir?', 'Eylül', ['Mai ve Siyah', 'Zehra', 'Sergüzeşt'], 'Mehmet Rauf\'un Eylül\'ü (1901), olaydan çok kişilerin iç dünyasını işleyen ilk olgun psikolojik roman sayılır.'),
  ('Namık Kemal\'in oğlu olan ve Servet-i Fünun çevresinde yer alan şair kimdir?', 'Ali Ekrem Bolayır', ['Ali Canip Yöntem', 'Faik Ali Ozansoy', 'Celal Sahir Erozan'], 'Ali Ekrem Bolayır, Namık Kemal\'in oğludur; Ordu\'nun Defteri gibi eserlerinde vatan temasını işlemiştir.'),
  ('Ahmet Rasim\'in yazılarının en belirgin özelliği hangisidir?', 'Halkın anlayacağı, sohbet havasında ve mizahi bir dil', ['Sembolist şiir kuramlarına ağırlık vermesi', 'Ağır Arapça ve Farsça tamlamalarla dolu bir üslup', 'Yalnız tarihî olaylara dayalı destansı bir anlatım'], 'Ahmet Rasim gazete okuruna seslenen, konuşur gibi yazan ve İstanbul\'un renkli hayatını mizahla yansıtan bir yazardır.'),
  ('Mehmet Emin Yurdakul\'un "Ben bir Türk\'üm, dinim, cinsim uludur" dizesiyle başlayan şiiri hangisidir?', 'Cenge Giderken', ['Ey Türk Uyan', 'Turan\'a Doğru', 'Ankara'], 'Cenge Giderken (1897), Türk-Yunan Savaşı sırasında yazılmış ve hece ölçüsüyle, sade Türkçeyle yazılmasıyla büyük yankı uyandırmıştır.'),
  ('Mehmet Emin Yurdakul\'un şiirleri Türk şiirinin gelişiminde neden önemli bir dönüm noktası sayılır?', 'Aruz yerine hece ölçüsünü ve sade Türkçeyi kullanarak millî şiire yön vermesi', ['Sembolizmi Türk şiirine ilk kez getirmesi', 'Serbest müstezat biçimini icat etmesi', 'Divan şiirini en saf biçimiyle yeniden canlandırması'], 'Servet-i Fünun\'un ağır dilinin hâkim olduğu yıllarda Mehmet Emin, halkın diliyle ve hece ölçüsüyle yazarak millî şiirin öncüsü oldu.'),
  ('Mehmet Emin Yurdakul\'a verilen unvan hangisidir?', 'Millî Şair', ['Şair-i Âzam', 'Hâce-i Evvel', 'Vatan Şairi'], 'Mehmet Emin\'e "Millî Şair" denir; Şair-i Âzam Abdülhak Hamit\'e, Hâce-i Evvel Ahmet Mithat\'a, Vatan Şairi Namık Kemal\'e verilen unvanlardır.'),
  ('Mehmet Emin Yurdakul\'un ilk şiir kitabının adı nedir?', 'Türkçe Şiirler', ['Türk Sazı', 'Ey Türk Uyan', 'Turana Doğru'], 'Türkçe Şiirler (1898/1899), Mehmet Emin\'in hece ölçüsüyle yazdığı şiirleri içeren ilk kitabıdır.'),
  ('Fecr-i Âti topluluğunun adının anlamı nedir?', 'Geleceğin şafağı', ['Yeni edebiyat', 'Genç kalemler', 'Millî ses'], 'Fecr-i Âti "gelecek şafak, geleceğin aydınlığı" demektir; topluluk 1909\'da kurulmuştur.'),
  ('Fecr-i Âti beyannamesinde yer alan ve topluluğun sanat anlayışını özetleyen ünlü ilke hangisidir?', '"Sanat şahsi ve muhteremdir."', ['"Sanat toplum içindir."', '"Halka doğru gitmeliyiz."', '"Güzel dil Türkçe bize."'], 'Fecr-i Âti, 1910\'da yayımladığı beyannamede sanatın kişisel ve saygıdeğer olduğunu belirterek Servet-i Fünun\'un bireyci çizgisini sürdürdü.'),
  ('Ahmet Haşim\'in yayımlanan ilk şiir kitabı hangisidir?', 'Göl Saatleri', ['Piyale', 'Bize Göre', 'Gurabahane-i Laklakan'], 'Göl Saatleri (1921) Haşim\'in ilk şiir kitabıdır; Piyale (1926) ikinci kitabıdır. Diğer ikisi düzyazı eserleridir.'),
  ('Ahmet Haşim\'in şiirlerinde en çok yer verdiği zaman dilimi ve renkler hangi seçenekte doğru verilmiştir?', 'Akşam, gurup vakti; kırmızı, sarı, altın renkleri', ['Sabah, gün doğumu; beyaz, mavi ve gümüş renkleri', 'Öğle vakti; yeşil ve kahverengi', 'Gece yarısı; yalnız siyah renk'], 'Haşim\'in şiirinde akşam, gün batımı, kızıl ve altın renkler, havuz, göl gibi imgeler baskındır.'),
  ('"Merdiven", "O Belde", "Bir Günün Sonunda Arzu" şiirlerinin ortak şairi kimdir?', 'Ahmet Haşim', ['Tevfik Fikret', 'Yahya Kemal Beyatlı', 'Cenap Şahabettin'], 'Bu şiirler Ahmet Haşim\'in sembolist şiirinin en tanınmış örneklerindendir.'),
  ('Ahmet Haşim\'in şiirinin hangi Batı akımıyla en çok ilişkilendirildiği sorulduğunda verilebilecek en doğru yanıt hangisidir?', 'Sembolizm', ['Realizm', 'Natüralizm', 'Klasisizm'], 'Haşim, anlamdan çok çağrışıma ve musikiye dayanan şiiriyle Türk sembolizminin en önemli temsilcisidir.'),
  ('Ahmet Haşim\'in "Bize Göre" adlı eseri hangi türdedir?', 'Deneme ve sohbet yazıları', ['Şiir kitabı', 'Roman', 'Tiyatro'], 'Bize Göre (1928), Haşim\'in çeşitli konulardaki düşüncelerini anlattığı deneme ve fıkra niteliğindeki yazılarından oluşur.'),
  ('Millî Edebiyat akımının başlangıcı sayılan ve 1911\'de Genç Kalemler\'de imzasız yayımlanan makale hangisidir?', 'Yeni Lisan', ['Şiir ve İnşa', 'Edebiyat ve Hukuk', 'Dekadanlar'], 'Ömer Seyfettin\'in kaleme aldığı Yeni Lisan makalesi, yazı dilinin konuşma diline yaklaştırılmasını ve Türkçeleşmesini savunmuştur.'),
  ('Millî Edebiyat döneminde hece ölçüsünün yaygınlaşması hangi anlayışın sonucudur?', 'Halkın şiir geleneğine ve millî kaynaklara yönelme', ['Divan şiirini sürdürme', 'Fransız sembolizmini ve parnasizmini taklit etme isteği', 'Fars şiirinden yeni kalıplar alma'], 'Millî Edebiyat sanatçıları halk edebiyatını millî kaynak saydı ve aruz yerine hece ölçüsünü "millî vezin" olarak benimsedi.'),
  ('Millî Edebiyat döneminde roman ve hikâyede Anadolu\'nun ön plana çıkması aşağıdakilerden hangisiyle ilişkilidir?', 'Millî bilincin güçlenmesi ve halka doğru yönelme', ['Servet-i Fünun\'un yalı merakının sürdürülmesi', 'Sansür nedeniyle İstanbul\'un anlatılmasının yasaklanması', 'Yazarların İstanbul\'u terk edip Anadolu\'ya yerleşmek zorunda kalması'], 'Balkan ve Birinci Dünya Savaşları ile güçlenen millî bilinç, yazarları Anadolu\'yu ve halkı keşfetmeye yöneltti.'),
  ('Ömer Seyfettin\'in hikâyelerinin en belirgin özelliği hangisidir?', 'Sade ve akıcı bir dille olay hikâyesi tarzında yazılmış olmaları', ['Ağır tamlamalarla süslü bir üslup', 'Olaydan çok durumun ön planda olduğu, şiirsel bir anlatıma dayanmaları', 'Bilinç akışı tekniğinin yaygın kullanımı'], 'Ömer Seyfettin, Maupassant tarzı olay hikâyesinin Türk edebiyatındaki en önemli temsilcisidir; dili sade ve konuşma diline yakındır.'),
  ('Ömer Seyfettin\'in çocukluk anısından yola çıkan ve gümüş bir at tımarı aracının kırılmasıyla başlayan hikâyesi hangisidir?', 'Kaşağı', ['Falaka', 'Pembe İncili Kaftan', 'Forsa'], 'Kaşağı\'da anlatıcı, değerli kaşağıyı kırıp suçu kardeşi Hasan\'a yükler; Hasan\'ın ölümü onda ömür boyu süren bir pişmanlık bırakır.'),
  ('Kaşağı hikâyesinin okura verdiği temel ileti nedir?', 'Yalanın ve haksız suçlamanın telafisi güç acılara yol açabileceği', ['Zenginliğin insanı mutlu edeceği', 'Hayvanların insanlardan daha akıllı olduğu', 'Kardeşler arasındaki rekabetin zararsız ve hatta geliştirici olduğu'], 'Anlatıcının yalanı yüzünden kardeşi ceza alır; kardeşin ölümüyle bu yalan telafi edilemez bir vicdan azabına dönüşür.'),
  ('Ömer Seyfettin\'in Pembe İncili Kaftan hikâyesinde Muhsin Çelebi\'nin kaftanını yere bırakıp çıkmasının anlamı nedir?', 'Türk elçisine gösterilen saygısızlığa onurlu bir karşılık vermek', ['Kaftanı hediye ederek dostluk kurmak', 'Kaftanın değersiz olduğunu göstermek', 'Elçilik görevinden istifa ettiğini ve İstanbul\'a döneceğini bildirmek'], 'Kendisine oturacak yer verilmeyen Muhsin Çelebi kaftanını yere serip üstüne oturur, giderken de bırakır; bu davranış Türk elçisinin onurunu korur.'),
  ('Ömer Seyfettin\'in Trablusgarp Savaşı sırasında İtalyan bir anneden doğan bir çocuğun kimlik çatışmasını işlediği hikâyesi hangisidir?', 'Primo Türk Çocuğu', ['Beyaz Lale', 'Bomba', 'Kesik Bıyık'], 'Primo Türk Çocuğu\'nda Kenan\'ın İtalyan karısından olan oğlu Primo, savaşın patlamasıyla Türk kimliğini seçer.'),
  ('Ömer Seyfettin\'in hikâyelerinde sıkça ele aldığı konular arasında aşağıdakilerden hangisi yer almaz?', 'Servet-i Fünun yalılarındaki aşk ve ihanet', ['Tarihî kahramanlık olayları ve akıncı gazaları', 'Balkanlardaki millî mücadele', 'Batı özentisinin eleştirisi'], 'Yalı çevresindeki aşk ve ihanet, Halit Ziya ve Mehmet Rauf\'un romanlarına özgüdür; Ömer Seyfettin ise tarih, millî mücadele ve toplum eleştirisine yönelmiştir.'),
  ('Ömer Seyfettin\'in kısa yaşamında çok sayıda hikâye yazması ve bunların okullarda yaygınca okutulması, onun Türk hikâyeciliğindeki rolü için neyi gösterir?', 'Hikâyeyi geniş okur kitlesine sevdiren bir öncü olduğunu', ['Hikâyenin yalnız seçkin ve eğitimli okurlara hitap edebileceğine inandığını', 'Hikâyeyi şiirin bir alt türü olarak gördüğünü', 'Hikâyede Divan üslubunu yeniden canlandırdığını'], 'Sade dili, merak uyandıran kurgusu ve millî konularıyla Ömer Seyfettin, hikâyeyi geniş kitlelere ulaştırmış bir öncüdür.'),
  ('Ömer Seyfettin\'in hikâyelerinin dil bakımından önemi için en doğru yargı hangisidir?', 'Yeni Lisan ilkelerini uygulayarak sade Türkçenin edebî gücünü göstermesi', ['Servet-i Fünun dilini sürdürüp sade dile karşı çıkan çevrelerce örnek gösterilmesi', 'Arapça ve Farsça kelimeleri çoğaltması', 'Divan nesrini örnek alması'], 'Ömer Seyfettin, Yeni Lisan\'da savunduğu ilkeleri hikâyelerinde uygulayarak konuşma diline dayalı bir edebî dilin mümkün olduğunu gösterdi.'),
  ('Ziya Gökalp\'in "Vatan ne Türkiye\'dir Türklere ne Türkistan / Vatan büyük ve müebbet bir ülkedir: Turan" dizelerinin yer aldığı şiiri hangisidir?', 'Turan', ['Lisan', 'Altın Destan', 'Kızıl Elma Neşidesi'], 'Turan şiiri, Gökalp\'in Türk dünyasının birliği düşüncesini dile getiren en tanınmış şiirlerindendir.'),
  ('"Güzel dil Türkçe bize, başka dil gece bize" dizesiyle başlayan ve dil konusundaki görüşleri manzum biçimde anlatan şiir kimindir?', 'Ziya Gökalp', ['Mehmet Emin Yurdakul', 'Ömer Seyfettin', 'Rıza Tevfik Bölükbaşı'], 'Ziya Gökalp\'in "Lisan" şiiri, Yeni Lisan ilkelerini ve halkın konuştuğu Türkçeye dayalı yazı dili düşüncesini anlatır.'),
  ('Ziya Gökalp\'in fikir eserleri arasında Türkçülüğün ilkelerini sistemli biçimde açıkladığı kitap hangisidir?', 'Türkçülüğün Esasları', ['Kızıl Elma', 'Altın Işık', 'Yeni Hayat'], 'Türkçülüğün Esasları (1923), Gökalp\'in dil, sanat, ahlak, hukuk gibi alanlarda Türkçülük programını ortaya koyduğu eserdir.'),
  ('Mehmet Akif Ersoy\'un bütün şiirlerini topladığı yedi kitaplık eserinin ortak adı nedir?', 'Safahat', ['Harabat', 'Rübab-ı Şikeste', 'Kendi Gök Kubbemiz'], 'Safahat "aşamalar, görünüşler" anlamına gelir ve Akif\'in yedi şiir kitabını kapsar.'),
  ('Safahat\'ı oluşturan kitaplar arasında aşağıdakilerden hangisi yer almaz?', 'Haluk\'un Defteri', ['Asım', 'Gölgeler', 'Süleymaniye Kürsüsünde'], 'Haluk\'un Defteri Tevfik Fikret\'e aittir; Asım, Gölgeler ve Süleymaniye Kürsüsünde Safahat\'ın kitaplarındandır.'),
  ('Mehmet Akif\'in "Çanakkale Şehitlerine" şiiri Safahat\'ın hangi kitabında yer alır?', 'Asım', ['Hakkın Sesleri', 'Hatıralar', 'Gölgeler'], 'Çanakkale Şehitlerine, Asım\'ın içinde yer alan ve Çanakkale savaşlarını destansı bir dille anlatan ünlü şiirdir.'),
  ('Asım kitabında Köse İmam ile Hocazade arasındaki konuşmalarda öne çıkan Asım adlı gencin temsil ettiği değer nedir?', 'Hem inançlı hem bilgili, geleceği kuracak ideal Türk genci', ['Batı\'yı körü körüne taklit eden, kendi değerlerine yabancı alafranga genç', 'Dünyadan el çekmiş bir derviş', 'Savaştan kaçan korkak bir genç'], 'Akif, Çanakkale\'de savaşmış Asım\'ı gençliğe örnek gösterir ve onu bilime ve çalışmaya yönelmeye çağırır.'),
  ('Mehmet Akif\'in aruz ölçüsünü kullanışı için hangisi doğrudur?', 'Aruzu konuşma diline büyük bir başarıyla uygulamıştır.', ['Aruzu bırakıp yalnız hece ölçüsüyle yazmıştır.', 'Aruzda sık sık ölçü hatası yapmıştır.', 'Yalnız serbest nazımla yazmıştır.'], 'Akif aruzu Türkçenin konuşma diliyle uyumlu biçimde kullanmış ve bu ölçüyle neredeyse düzyazı rahatlığında söyleyiş elde etmiştir.'),
  ('Mehmet Akif Ersoy\'un mesleği neydi?', 'Veteriner hekim', ['Hukukçu', 'Mühendis', 'Asker'], 'Akif, Halkalı Baytar Mektebi\'ni bitirmiş ve uzun yıllar baytar (veteriner) olarak devlet hizmetinde çalışmıştır.'),
  ('İstiklal Marşı\'nın kabul edildiği tarih ve kurum hangi seçenekte doğru verilmiştir?', '12 Mart 1921, Türkiye Büyük Millet Meclisi', ['29 Ekim 1923, Cumhurbaşkanlığı', '23 Nisan 1920, Heyet-i Temsiliye', '1 Kasım 1922, Maarif Vekâleti'], 'İstiklal Marşı, 12 Mart 1921\'de TBMM\'de kabul edilmiştir.'),
  ('İstiklal Marşı\'nın ithaf edildiği kesim kimdir?', 'Kahraman Ordumuz', ['Türk Gençliği', 'Şehit Anneleri', 'Türk Milleti\'nin Kadınları'], 'Akif İstiklal Marşı\'nı "Kahraman Ordumuza" ithaf etmiştir.'),
  ('"Korkma, sönmez bu şafaklarda yüzen al sancak" dizesinde şairin "korkma" diye seslenmesi hangi amaca yöneliktir?', 'Milletin bağımsızlığa olan inancını güçlendirmek', ['Düşmanı övmek', 'Doğa güzelliğini anlatmak', 'Geçmişe özlem duymak ve kaybedilen toprakların yasını tutmak'], 'İstiklal Marşı\'nın ilk dizesi, umutsuzluğa düşebilecek millete güven aşılayan bir seslenmedir; marşın coşkulu ve inanç dolu tonunu kurar.'),
  ('Yahya Kemal Beyatlı\'nın "Artık demir almak günü gelmişse zamandan" dizesiyle başlayan ve ölümü bir yolculuk olarak ele alan şiiri hangisidir?', 'Sessiz Gemi', ['Açık Deniz', 'Rindlerin Ölümü', 'Ses'], 'Sessiz Gemi\'de ölüm, limandan bir daha dönmemek üzere ayrılan bir gemi imgesiyle anlatılır.'),
  ('Yahya Kemal\'in İstanbul\'u ve İstanbul\'un semtlerini anlattığı düzyazılarından oluşan eser hangisidir?', 'Aziz İstanbul', ['Bize Göre', 'Şehir Mektupları', 'Eğil Dağlar'], 'Aziz İstanbul, Yahya Kemal\'in İstanbul\'a dair denemelerinden oluşur; Eğil Dağlar ise Millî Mücadele yıllarındaki makalelerini içerir.'),
  ('Yahya Kemal\'in şiirinde ölçü konusundaki tutumu için hangisi doğrudur?', 'Şiirlerini neredeyse tamamen aruzla, kusursuz bir biçim titizliğiyle yazmıştır.', ['Bütün şiirlerini hece ölçüsüyle yazıp aruzu millî olmadığı gerekçesiyle reddetmiştir.', 'Serbest nazmın öncüsü olmuştur.', 'Aruz ve heceyi eşit sayıda şiirde kullanmıştır.'], 'Yahya Kemal, Millî Edebiyat\'ın hece tercihine karşın aruzu Türkçeye en uygun biçimde kullanan şairlerdendir; "Ok" gibi pek az şiiri hecelidir.'),
  ('Yahya Kemal\'in doğduğu şehir hangisidir?', 'Üsküp', ['Selanik', 'Bağdat', 'Manastır'], 'Yahya Kemal 1884\'te Üsküp\'te doğmuş; Rumeli\'yi kaybetmenin acısı onun şiirinde ve tarih anlayışında iz bırakmıştır.'),
  ('Yahya Kemal\'in akıncı ruhunu dile getiren ve "Bin atlı akınlarda çocuklar gibi şendik" dizesiyle başlayan şiiri hangisidir?', 'Akıncılar', ['Mohaç Türküsü', 'Açık Deniz', 'Itri'], 'Akıncılar şiiri, Osmanlı akıncılarının coşkusunu ve ölüme karşı neşeli tavrını anlatır.'),
  ('Yahya Kemal\'in şiirlerinde sık görülen konular arasında aşağıdakilerden hangisi yer almaz?', 'Köy hayatının sorunları ve toprak reformu', ['İstanbul, Boğaziçi ve İstanbul semtleri', 'Osmanlı tarihi ve zaferleri', 'Aşk, ölüm ve zaman'], 'Yahya Kemal\'in şiirinde köy sorunları yer almaz; o İstanbul\'u, tarihi, aşkı ve ölümü işlemiştir.'),
  ('Halide Edip Adıvar\'ın Millî Mücadele\'yi konu alan ilk romanı hangisidir?', 'Ateşten Gömlek', ['Vurun Kahpeye', 'Sinekli Bakkal', 'Handan'], 'Ateşten Gömlek (1922), Millî Mücadele\'yi anlatan ilk roman olarak bilinir; Vurun Kahpeye de aynı konuyu işler.'),
  ('Halide Edip\'in Vurun Kahpeye romanının kahramanı olan öğretmen kimdir?', 'Aliye', ['Feride', 'Rabia', 'Ayşe'], 'Vurun Kahpeye\'de idealist öğretmen Aliye, işgal döneminde bir Anadolu kasabasında yobaz ve işbirlikçilerin kurbanı olur.'),
  ('Reşat Nuri Güntekin\'in Çalıkuşu romanının kahramanı Feride\'nin İstanbul\'dan ayrılıp Anadolu\'ya gitmesinin nedeni nedir?', 'Nişanlısı Kamran\'ın kendisini aldattığını öğrenmesi', ['Babasının sürgüne gönderilmesi', 'Ailesinin iflas edip konağı kaybetmesi', 'Savaşta yaralanan kardeşini bulmak ve ona bakmak istemesi'], 'Feride, Kamran\'ın başka bir kadınla ilişkisini öğrenince evden kaçar ve Anadolu\'da öğretmenlik yapmaya başlar.'),
  ('Reşat Nuri Güntekin\'in Yeşil Gece romanında öğretmen Şahin Efendi\'nin mücadele ettiği kesim hangisidir?', 'Bağnaz softalar ve yobazlık', ['İşgalci ordular ve onlarla iş birliği yapanlar', 'Toprak ağaları ve tefeciler', 'Saray çevresi ve paşalar'], 'Yeşil Gece (1928), medrese öğrencisi iken aydınlanan Şahin Efendi\'nin Sarıova\'da yobazlığa karşı verdiği mücadeleyi anlatır.'),
  ('Reşat Nuri\'nin Yaprak Dökümü romanında aile reisi Ali Rıza Bey\'in temsil ettiği değer hangisidir?', 'Geleneksel ahlak ve dürüstlük', ['Savaş kahramanlığı ve cephe hayatı', 'Alafranga yaşam, gösteriş ve israf', 'Dinî bağnazlık'], 'Ali Rıza Bey dürüstlüğü yüzünden memuriyetten ayrılan, eski değerlere bağlı bir babadır; çocukları ise yeni hayatın cazibesine kapılıp aileyi dağıtır.'),
  ('Yaprak Dökümü romanının adı, olay örgüsü düşünüldüğünde neyi simgeler?', 'Ailenin ve geleneksel değerlerin birer birer çözülmesini', ['Sonbaharda bir köy düğününü', 'Bir bahçıvanın hayatını', 'Savaştan dönen askerlerin sevincini ve köydeki şenlikleri'], 'Ağaçtan düşen yapraklar gibi ailenin bireyleri ve değerleri teker teker dağılır.'),
  ('Reşat Nuri Güntekin\'in romanlarının dil ve üslup bakımından en belirgin özelliği hangisidir?', 'Sade, akıcı ve konuşma diline yakın bir dil kullanması', ['Ağır tamlamalı ve süslü bir dil kullanması', 'Bilinç akışı tekniğini sürekli uygulaması', 'Diyalog kullanmaktan kaçınıp uzun iç konuşmalara yer vermesi'], 'Reşat Nuri, geniş okur kitlesine ulaşan sade ve akıcı diliyle Türk romanının en çok okunan yazarlarındandır.'),
  ('Yakup Kadri\'nin Nur Baba romanında konu edindiği çevre hangisidir?', 'Bir Bektaşi tekkesi', ['Bir askerî kışla ve cephe gerisi', 'Bir köy okulu', 'Bir Paris salonu'], 'Nur Baba, bir Bektaşi tekkesindeki yozlaşmayı ve şeyhin etkisine kapılan insanları anlatır.'),
  ('Yakup Kadri\'nin Sodom ve Gomore romanında işlediği dönem hangisidir?', 'Mütareke yıllarında işgal altındaki İstanbul', ['Tanzimat\'ın ilan edildiği yıllarda saray çevresi', 'Balkan Savaşları sırasında Selanik', 'Cumhuriyet\'in ilk yıllarında Ankara'], 'Sodom ve Gomore, işgal altındaki İstanbul\'da işgalcilerle iş birliği yapan çevrelerin ahlaki çöküşünü anlatır.'),
  ('Yakup Kadri\'nin Yaban romanında aydın ile köylü arasındaki uçurumu anlatan başkahraman kimdir?', 'Ahmet Celal', ['Hakkı Celis', 'Ahmet Kerim', 'Doktor Hikmet'], 'Yaban\'da Birinci Dünya Savaşı\'nda kolunu kaybeden yedek subay Ahmet Celal, emir eri Mehmet Ali\'nin köyüne yerleşir ve köylü tarafından "yaban" olarak görülür.'),
  ('Yaban romanının dili için dikkat çeken özellik nedir?', 'Köylülerin konuşmalarında yöresel ağız özelliklerine yer verilmesi', ['Bütünüyle Arapça ve Farsça tamlamalarla dolu ağır bir Osmanlıcayla yazılması', 'Diyalogların tamamen Fransızca olması', 'Anlatımın manzum olması'], 'Yakup Kadri, köylülerin konuşmalarını kendi ağızlarıyla vererek romanın gerçekçiliğini artırmıştır.'),
  ('Reşat Nuri Güntekin\'in romanlarında sıkça rastlanan kahraman tipi hangisidir?', 'Anadolu\'ya giden idealist öğretmen ya da memur', ['Alafranga, gösteriş meraklısı bir sosyete kadını', 'Saray entrikacısı paşa', 'Bilim insanı gezgin'], 'Feride, Şahin Efendi, Zehra gibi kahramanlar Anadolu\'da görev yapan idealist öğretmenlerdir.'),
  ('Refik Halit Karay\'ın Anadolu\'da sürgünde bulunduğu yıllarda yazdığı ve Anadolu insanını gerçekçi biçimde anlatan hikâye kitabı hangisidir?', 'Memleket Hikâyeleri', ['Gurbet Hikâyeleri', 'Çağlayanlar', 'Küçük Şeyler'], 'Memleket Hikâyeleri (1919), Refik Halit\'in Sinop, Çorum, Bilecik gibi sürgün yerlerindeki gözlemlerine dayanır.'),
  ('Refik Halit Karay\'ın mizahi ve siyasi yazılarında kullandığı takma ad hangisidir?', 'Kirpi', ['Server Bedi', 'Çalıkuşu', 'Tiryaki'], 'Refik Halit, İttihat ve Terakki\'yi eleştirdiği mizahi yazılarını "Kirpi" imzasıyla yayımlamıştır; Server Bedi ise Peyami Safa\'nın takma adıdır.'),
  ('Millî Edebiyat döneminde hece ölçüsüyle yazan ve "Beş Hececiler" adıyla anılan şairler arasında aşağıdakilerden hangisi yer almaz?', 'Ahmet Haşim', ['Faruk Nafiz Çamlıbel', 'Enis Behiç Koryürek', 'Orhan Seyfi Orhon'], 'Beş Hececiler: Faruk Nafiz, Enis Behiç, Orhan Seyfi, Halit Fahri ve Yusuf Ziya\'dır; Ahmet Haşim aruzla yazan sembolist bir şairdir.'),
  ('Faruk Nafiz Çamlıbel\'in Anadolu\'ya yaptığı bir yolculuğu hanların duvarlarına yazılmış dizeler aracılığıyla anlattığı ünlü şiiri hangisidir?', 'Han Duvarları', ['Çoban Çeşmesi', 'Akıncılar', 'Sessiz Gemi'], 'Han Duvarları, Faruk Nafiz\'in hece ölçüsüyle yazdığı, Anadolu\'yu ve gurbeti anlatan en tanınmış şiiridir.'),
  ('Faruk Nafiz Çamlıbel\'in "Derinden derine ırmaklar ağlar" dizesiyle başlayan şiirinin adı nedir?', 'Çoban Çeşmesi', ['Han Duvarları', 'Sanat', 'Dinle Neyden'], 'Çoban Çeşmesi, Faruk Nafiz\'in halk şiirinin söyleyişine yaklaşan, hece ölçüsüyle yazılmış şiiridir.'),
  ('Millî Mücadele\'yi konu alan romanlar arasında aşağıdakilerden hangisi yer almaz?', 'Aşk-ı Memnu', ['Ateşten Gömlek', 'Vurun Kahpeye', 'Yaban'], 'Aşk-ı Memnu (1900), Servet-i Fünun döneminde yazılmış bir aile ve aşk romanıdır; diğerleri Millî Mücadele yıllarını işler.'),
  ('Millî Edebiyat döneminde aruzla yazmayı sürdüren ve hece ölçüsüne geçmeyen şairler hangi seçenekte birlikte verilmiştir?', 'Yahya Kemal ve Mehmet Akif', ['Faruk Nafiz ve Orhan Seyfi', 'Ziya Gökalp ve Mehmet Emin', 'Halit Fahri ve Yusuf Ziya'], 'Yahya Kemal ve Mehmet Akif, dönemin hece akımına katılmayıp aruzu ustalıkla kullanmayı sürdüren şairlerdir.'),
  ('Millî Edebiyat şiirinde halk edebiyatına yönelişin bir sonucu olarak aşağıdakilerden hangisi görülür?', 'Koşma, mani, türkü gibi halk şiiri biçimlerinin kullanılması', ['Gazel ve kaside biçimlerinin yaygınlaşması', 'Sone ve terza rimanın tek biçim olması', 'Serbest nazmın tümüyle egemen olması'], 'Millî Edebiyat şairleri hece ölçüsüyle birlikte halk şiirinin biçimlerine ve söyleyişine de yönelmişlerdir.'),
  ('Ziya Gökalp\'in edebiyatta "halka doğru" düşüncesi en çok hangi sonucu doğurmuştur?', 'Yazarların halkın dilini, hayatını ve kültürünü konu edinmesi', ['Yazarların yalnız saray çevresine seslenmesi', 'Edebiyatın tümüyle Fransızca yazılması', 'Halk edebiyatının değersiz sayılması'], '"Halka doğru" anlayışı, aydınların halkı tanıması ve edebiyatın halkın diline ve yaşamına yönelmesi demektir.'),
  ('Türk edebiyatındaki topluluk ve dönemlerin ortaya çıkış sırası hangi seçenekte doğru verilmiştir?', 'Tanzimat → Servet-i Fünun → Fecr-i Âti → Millî Edebiyat', ['Servet-i Fünun → Tanzimat → Millî Edebiyat → Fecr-i Âti', 'Tanzimat → Fecr-i Âti → Servet-i Fünun → Millî Edebiyat', 'Millî Edebiyat → Fecr-i Âti → Tanzimat → Servet-i Fünun'], 'Tanzimat 1860\'ta, Servet-i Fünun 1896\'da, Fecr-i Âti 1909\'da, Millî Edebiyat ise 1911\'de Yeni Lisan ile başlar.'),
  ('Tanzimat\'ın ilk kuşağında "hürriyet, vatan, millet, eşitlik" gibi kavramların edebiyata girmesinin kaynağı nedir?', 'Fransız İhtilali\'nin yaydığı fikirler', ['Divan şiirinin mazmunları ve sembolleri', 'Halk şiirinin geleneksel temaları', 'Tasavvuf felsefesi'], 'Bu kavramlar Fransız İhtilali ile Avrupa\'da yayılan düşüncelerle Osmanlı aydınlarına ulaşmış ve Tanzimat edebiyatına girmiştir.'),
  ('Bir edebiyat tarihçisi "Bu yazar Şair Evlenmesi\'ni yazmış, Tercüman-ı Ahval\'i çıkarmış, atasözleri derlemiştir." diyorsa hangi yazarı anlatmaktadır?', 'Şinasi', ['Ahmet Mithat Efendi', 'Namık Kemal', 'Ziya Paşa'], 'Şair Evlenmesi, Tercüman-ı Ahval ve Durub-ı Emsal-i Osmaniye Şinasi\'ye aittir.'),
  ('Bir edebiyat tarihçisi "Divan şiirinden bir antoloji hazırlamış, Terkib-i Bend ile tanınmış, Âli Paşa\'yı hicvetmiştir." diyorsa sözü edilen sanatçı kimdir?', 'Ziya Paşa', ['Muallim Naci', 'Abdülhak Hamit', 'Şemsettin Sami'], 'Harabat antolojisi, Terkib-i Bend ve Zafername Ziya Paşa\'nın eserleridir.'),
  ('Tevfik Fikret\'in "Haluk\'un Vedaı" şiirinde oğlunu hangi amaçla uğurladığı anlatılır?', 'Yurt dışında öğrenim görmesi için', ['Cepheye savaşa gitmesi için', 'Hacca gitmesi için', 'Evlenip başka şehre yerleşmesi için'], 'Haluk, mühendislik öğrenimi için İskoçya\'ya gönderilir; Fikret bu ayrılığı umutla karışık bir hüzünle anlatır.'),
  ('Mehmet Rauf\'un Eylül romanının adı ile roman arasındaki ilişki nasıl yorumlanabilir?', 'Sonbaharın hüzünlü havası, kişilerin karamsar ruh hâlini ve aşkın sonunu simgeler.', ['Romanın Eylül adlı genç bir kadının hayatını ve onun yaşadığı aşkı anlatmasını gösterir.', 'Olayların bir okulun açılışında geçmesini anlatır.', 'Bir savaşın başlangıç tarihini belirtir.'], 'Eylül\'de sonbahar, kişilerin iç dünyasıyla uyumlu bir mevsim olarak kullanılır; doğa ile ruh hâli arasında bağ kurulur.'),
  ('"Ey şehit oğlu şehit, isteme benden makber / Sana ağuşunu açmış duruyor Peygamber" dizeleri hangi şiirden alınmıştır?', 'Çanakkale Şehitlerine', ['İstiklal Marşı', 'Bülbül', 'Süleymaniye\'de Bayram Sabahı'], 'Bu dizeler Mehmet Akif\'in Çanakkale Şehitlerine şiirinden alınmıştır; şair şehide mezar yapamayacağını, onun büyüklüğüne bir mezarın yetmeyeceğini söyler.'),
  ('"Bastığın yerleri toprak diyerek geçme, tanı / Düşün altındaki binlerce kefensiz yatanı" dizelerinde şair okurdan ne istemektedir?', 'Vatan toprağının şehitlerin kanıyla kazanıldığını bilmesini', ['Yurdu bırakıp göç etmesini', 'Toprağı ekip biçmesini ve ondan bereket beklemesini', 'Doğanın güzelliğini seyretmesini'], 'İstiklal Marşı\'ndaki bu dizelerde şair, vatan toprağının şehitlerin emanetiyle kutsallaştığını hatırlatır.'),
  ('Mehmet Akif\'in şiirlerinde "Asım\'ın nesli" ifadesiyle kastettiği kimdir?', 'Çalışkan, inançlı ve vatanına bağlı yeni Türk gençliği', ['Batı\'ya özenen İstanbul gençliği', 'Savaştan kaçan asker kaçakları', 'Medreseden yetişen, yeniliğe kapalı eski kuşak'], 'Akif, Asım\'ı bilime, çalışmaya ve inanca bağlı ideal gençliğin simgesi olarak gösterir; "Asım\'ın nesli" bu gençliği anlatır.'),
  ('Mehmet Akif\'in "Küfe" şiirinde anlatılan durum nedir?', 'Yoksul bir adamın küfeyle yük taşıyarak ailesini geçindirme çabası', ['Bir askerin cephe anıları', 'Bir çocuğun mahalle mektebindeki ilk günü', 'Bir şairin aşk acısı'], 'Küfe\'de sırtında küfeyle hamallık yapan yoksul bir babanın dramı, manzum hikâye biçiminde anlatılır.'),
  ('"Eteklerinde güneş rengi bir yığın yaprak / Ve bir zaman bakacaksın semâya ağlayarak" dizeleri Ahmet Haşim\'in hangi şiirinden alınmıştır?', 'Merdiven', ['O Belde', 'Bir Günün Sonunda Arzu', 'Karanfil'], 'Merdiven, Haşim\'in akşam ve gurup imgeleriyle kurulmuş en tanınmış şiirlerindendir.'),
  ('Ahmet Haşim\'in şiirleri ile Mehmet Akif\'in şiirleri karşılaştırıldığında temel farklılık hangisidir?', 'Haşim\'in içe dönük ve imgeci, Akif\'in toplumcu ve gerçekçi olması', ['Haşim\'in hece, Akif\'in serbest ölçüyle yazması', 'Haşim\'in Tanzimat, Akif\'in Servet-i Fünun şairi olması', 'Haşim\'in yalnız destan, Akif\'in yalnız aşk şiiri yazmış olması'], 'Haşim bireysel ve sembolist bir şiir kurar; Akif ise toplumun sorunlarını gözlemci bir dille işler.'),
  ('Yahya Kemal\'in "Rindlerin Ölümü" şiirinde ölüme bakışı nasıl özetlenebilir?', 'Ölüm korkulacak bir son değil, huzurlu bir bahar ülkesidir.', ['Ölüm ancak savaşta anlamlıdır.', 'Ölüm bütün umutları yok eden karanlık ve korkunç bir sondur.', 'Ölüm bir cezadır ve kaçınılması gerekir.'], '"Ölüm âsûde bahar ülkesidir bir rinde" dizesinde olduğu gibi Yahya Kemal ölümü sakin ve güzel bir geçiş olarak görür.'),
  ('Halide Edip\'in Ateşten Gömlek romanındaki olayların geçtiği tarihî dönem hangisidir?', 'Yunanlıların İzmir\'i işgalinden sonraki Millî Mücadele yılları', ['Balkan Savaşları sırasında Selanik\'in kaybı', 'Tanzimat Fermanı\'nın ilanı', 'Kırım Savaşı'], 'Ateşten Gömlek, İzmir\'in işgaliyle başlayan direniş ve Anadolu\'daki Millî Mücadele yıllarını anlatır.'),
  ('Yakup Kadri\'nin Kiralık Konak romanının adı neyi simgeler?', 'Geleneksel değerlerin terk edilip konağın da aile bağlarının da çözülmesini', ['Bir emlak ticaretini', 'Konakta yaşayan bir kiracının hayatını ve ev sahibiyle kavgalarını', 'Savaşta yıkılan bir binayı'], 'Naim Efendi\'nin konağının sonunda kiraya verilmesi, eski aile düzeninin ve değerlerinin çöküşünü simgeler.'),
  ('Bir edebiyat öğretmeni tahtaya şu özellikleri yazıyor: "Beyit bütünlüğü bozulmuştur, sone ve serbest müstezat kullanılmıştır, dil ağırdır, konu bireyseldir." Bu özellikler hangi döneme aittir?', 'Servet-i Fünun', ['Tanzimat birinci kuşağı', 'Millî Edebiyat', 'Divan edebiyatının son dönemi'], 'Bu özelliklerin tümü Servet-i Fünun şiirinin ayırıcı nitelikleridir.'),
  ('"Hece ölçüsü kullanılmış, İstanbul Türkçesi esas alınmış, konular Anadolu\'dan ve millî tarihten seçilmiştir." Bu özellikler aşağıdaki dönemlerden hangisini tanımlar?', 'Millî Edebiyat', ['Servet-i Fünun', 'Fecr-i Âti', 'Tanzimat ikinci kuşağı'], 'Hece ölçüsü, sade İstanbul Türkçesi ve Anadolu\'ya yöneliş Millî Edebiyat\'ın temel ilkeleridir.'),
  ('"Vatan, hürriyet, adalet gibi kavramlar işlenmiş, ancak çoğunlukla kaside, gazel, terkib-i bend gibi eski biçimler kullanılmıştır." Bu açıklama hangi döneme uygundur?', 'Tanzimat birinci kuşağı', ['Servet-i Fünun', 'Millî Edebiyat', 'Divan edebiyatının son dönemi ve Lale Devri'], 'Tanzimat\'ın ilk kuşağı yeni kavramları büyük ölçüde Divan nazım biçimleriyle dile getirmiştir.'),
  ('Tanzimat ve Servet-i Fünun romanlarındaki alafranga tiplerin ortak eleştiri noktası nedir?', 'Batı\'yı özünden değil, dış görünüşünden ve eğlence yönünden taklit etmeleri', ['Bilimsel çalışmalara aşırı önem vermeleri', 'Batı dillerini çok iyi öğrenip çeviri yapmaları ve bilime yönelmeleri', 'Köy hayatına aşırı bağlı olmaları'], 'Felatun Bey, Bihruz Bey, Meftun Bey gibi tipler Batılılaşmayı kılık kıyafet, eğlence ve bozuk Fransızcadan ibaret sanır.'),
  ('"Sanat toplum içindir" anlayışını benimseyen sanatçılar hangi seçenekte birlikte verilmiştir?', 'Namık Kemal ve Ziya Gökalp', ['Cenap Şahabettin ve Ahmet Haşim', 'Mehmet Rauf ve Halit Ziya', 'Ahmet Haşim ve Emin Bülent'], 'Namık Kemal (Tanzimat) ve Ziya Gökalp (Millî Edebiyat) toplumu yönlendirmeyi amaçlayan bir sanat anlayışına sahiptir; diğerleri bireyci bir çizgidedir.'),
  ('Aşağıdakilerden hangisi Fecr-i Âti topluluğunun üyelerinden biri değildir?', 'Ömer Seyfettin', ['Ahmet Haşim', 'Yakup Kadri Karaosmanoğlu', 'Refik Halit Karay'], 'Ömer Seyfettin, Genç Kalemler çevresinde Millî Edebiyat\'ı başlatan yazardır; diğerleri Fecr-i Âti\'de yer almıştır.'),
  ('Aşağıdakilerden hangisi Servet-i Fünun topluluğunun üyesi değildir?', 'Muallim Naci', ['Tevfik Fikret', 'Halit Ziya Uşaklıgil', 'Mehmet Rauf'], 'Muallim Naci, eski edebiyatı savunan ve Servet-i Fünun\'dan önce ölen bir şairdir; diğerleri topluluğun önde gelen üyeleridir.'),
  ('"Bu yazar Anadolu\'da öğretmenlik ve müfettişlik yapmış; Çalıkuşu, Yeşil Gece ve Yaprak Dökümü romanlarını yazmıştır." Sözü edilen yazar kimdir?', 'Reşat Nuri Güntekin', ['Yakup Kadri Karaosmanoğlu', 'Halide Edip Adıvar', 'Ömer Seyfettin'], 'Bu romanlar ve hayat bilgileri Reşat Nuri Güntekin\'e aittir.'),
  ('Reşat Nuri Güntekin\'in Yeşil Gece romanının işlediği tema, Cumhuriyet\'in hangi ilkesiyle en çok ilişkilidir?', 'Laiklik', ['Devletçilik', 'Cumhuriyetçilik', 'Milliyetçilik'], 'Yeşil Gece, softalığa ve bağnazlığa karşı aydınlanma mücadelesini anlatarak laiklik düşüncesiyle örtüşür.'),
  ('Ömer Seyfettin\'in "Başını Vermeyen Şehit" ve "Topuz" gibi hikâyeleri hangi grupta değerlendirilir?', 'Tarihî konulu hikâyeler', ['Çocukluk anıları', 'Mizahi toplum eleştirileri', 'Aşk hikâyeleri'], 'Bu hikâyeler Türk tarihinden alınmış kahramanlık olaylarını işler.'),
  ('Ziya Gökalp\'in "Yeni Hayat" adlı şiir kitabının içeriği için hangisi doğrudur?', 'Toplumsal ve millî ülküleri işleyen şiirlerden oluşur.', ['Aşk ve doğa şiirlerinden oluşur.', 'Tasavvufi gazellerden ve ilahilerden oluşan bir divandır.', 'Fransızca şiirlerden oluşur.'], 'Yeni Hayat (1918), Gökalp\'in millî kültür, aile, ahlak ve dil konularındaki düşüncelerini dile getiren şiirlerini içerir.'),
  ('Balkan Savaşları\'ndaki yenilginin Türk edebiyatına en belirgin etkisi hangisidir?', 'Millî bilincin güçlenmesi ve millî konulu eserlerin artması', ['Edebiyatçıların Fransızca yazmaya başlaması', 'Divan şiirinin yeniden egemen olması', 'Edebiyatın toplumsal konulardan tamamen uzaklaşması'], 'Rumeli\'nin kaybı aydınlarda derin bir sarsıntı yarattı; Ömer Seyfettin\'in hikâyeleri ve Akif\'in Hakkın Sesleri bu acıyı yansıtır.'),
  ('"Zil, şal ve gül. Bu bahçede raksın bütün hızı" dizesiyle başlayan ve İspanyol dansını anlatan Yahya Kemal şiiri hangisidir?', 'Endülüs\'te Raks', ['Açık Deniz', 'Mohaç Türküsü', 'Sessiz Gemi'], 'Endülüs\'te Raks, flamenko dansının hızını ve renklerini ses ve ritimle canlandıran ünlü şiiridir.'),
  ('Mehmet Akif\'in "Mahalle Kahvesi" şiirinde eleştirdiği durum hangisidir?', 'İnsanların kahvehanelerde boş sohbetlerle vakit öldürmesi', ['Kahve fiyatlarının yükselmesi', 'Kahvecilerin vergi ödememesi', 'Mahallede kahvehane bulunmaması'], 'Akif bu manzumede çalışmak yerine kahvehanede tembellik eden, dedikoduyla vakit geçiren insanları eleştirir.'),
  ('Şair Evlenmesi\'nin dil ve üslup bakımından dikkat çeken özelliği hangisidir?', 'Kişilerin konuşmalarında halk dilinin ve deyimlerin kullanılması', ['Baştan sona Arapça yazılmış olması', 'Manzum olarak yazılması', 'Hiç diyalog içermeyip tek bir anlatıcının ağzından aktarılması'], 'Oyunda kişiler gündelik konuşma diliyle, atasözü ve deyimlerle konuşur; bu, Şinasi\'nin halk dilini önemsemesinin bir sonucudur.'),
  ('Reşat Nuri\'nin Çalıkuşu\'nda Feride\'nin Anadolu\'da karşılaştığı güçlükler hangi toplumsal soruna dikkat çeker?', 'Anadolu\'da eğitimin ve okulların yetersizliğine', ['İstanbul\'daki konut sıkıntısına ve kira fiyatlarının yüksekliğine', 'Avrupa\'daki savaşlara', 'Saraydaki siyasi entrikalara'], 'Feride\'nin öğretmenlik serüveni, Anadolu\'daki okulların yoksulluğunu ve eğitim alanındaki ihmali gözler önüne serer.'),
  ('Millî Edebiyat döneminde kadın yazarların eserlerinde öne çıkan ortak tema aşağıdakilerden hangisidir?', 'Kadının toplumdaki yeri ve millî mücadeledeki rolü', ['Yalnız saray hayatı', 'Bilimkurgu ve uzay yolculuğu', 'Divan şiirinin yeniden canlandırılması ve gazel biçiminin sürdürülmesi'], 'Halide Edip ve Müfide Ferit Tek gibi yazarlar kadının eğitimi, toplumsal rolü ve millî davadaki fedakârlığını işlemiştir.'),
  ('Aşağıdakilerden hangisi Millî Edebiyat\'ın ilkeleri arasında yer almaz?', 'Sanatın yalnız bireysel duyguları anlatması', ['Konuşma diline dayalı sade bir dil', 'Hece ölçüsünün kullanılması', 'Konuların halkın hayatından ve millî tarihten alınması'], 'Millî Edebiyat toplum ve millet için sanat anlayışını benimser; bireysel duygulara kapanmak Servet-i Fünun ve Fecr-i Âti\'nin özelliğidir.'),
  ('Aşağıdaki şairlerden hangisi şiirlerinde ağırlıklı olarak hece ölçüsünü kullanmıştır?', 'Faruk Nafiz Çamlıbel', ['Tevfik Fikret', 'Cenap Şahabettin', 'Yahya Kemal Beyatlı'], 'Faruk Nafiz Beş Hececiler\'dendir; diğer üç şair aruzla yazmıştır.'),
];
